#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES — restart daily NZ grocery scrapes on this Mac:
#   collector.env (Woolworths session cookie) → rendered launchd plist →
#   install + bootstrap → test run right now → verify fresh data landed.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

banner "Daily grocery scrape setup"

DEFAULT_REPO="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"

# collector.env is SOURCED by /bin/sh (archive-daily-local.sh does
# `set -a; . "$COLLECTOR_ENV_FILE"`), so values must be single-quoted —
# cookie headers contain spaces/semicolons, and unquoted $/backticks would
# execute at source time. Single quotes can't appear inside the value.
write_collector_env() {
  local key="$1" value="$2"
  if [[ "$value" == *"'"* ]]; then
    warn "$key contains a single quote (') — that cannot be stored safely."
    exit 1
  fi
  write_env "$key" "'$value'"
}

# ── Stage 1: locate repo + node ───────────────────────────────────────────
stage "Repo & Node paths"
say "launchd runs outside your shell profile, so it needs absolute paths."
ask REPO_PATH "Repo path:" 
REPO_PATH="${REPO_PATH:-$DEFAULT_REPO}"
if [[ ! -f "$REPO_PATH/scripts/archive-daily-local.sh" ]]; then
  warn "$REPO_PATH/scripts/archive-daily-local.sh not found — check the path."
  exit 1
fi
NODE_BIN=$(command -v node || true)
if [[ -z "$NODE_BIN" ]]; then
  warn "node not found on PATH; install Node 26+ first (brew install node)."
  exit 1
fi
say "repo:     $REPO_PATH"
say "node:     $NODE_BIN ($(node --version))"
note "The daily job collects: PAK'nSAVE (all stores), Woolworths (your login's"
note "store), New World (all stores), FreshChoice (all storefronts), Warehouse."

# ── Stage 2: collector.env — Woolworths session cookie ────────────────────
stage "collector.env — Woolworths cookie"
ENV_FILE="$REPO_PATH/collector.env"
say "Woolworths prices need your logged-in browser session (it also selects"
say "which fulfilment store gets collected)."
open_url "https://www.woolworths.co.nz/"
step "Log in, and pick your usual delivery/pickup store if prompted."
step "Open DevTools (F12) → Network tab → click any request to woolworths.co.nz."
step "Under Request Headers, right-click the Cookie header → Copy Value."
step "Paste the WHOLE Cookie header below (input is hidden)."
ask_secret WOOLWORTHS_COOKIE "Paste the Cookie header:"
if [[ -z "$WOOLWORTHS_COOKIE" ]]; then
  warn "Empty cookie — Woolworths collection will fail until one is provided."
fi
write_collector_env WOOLWORTHS_COOKIE "$WOOLWORTHS_COOKIE"
say "Optional — press Enter to collect ALL FreshChoice storefronts (slower),"
say "or pin one, e.g. https://queenstown.store.freshchoice.co.nz"
ask FRESHCHOICE_ORIGIN "FreshChoice origin (optional):"
[[ -n "$FRESHCHOICE_ORIGIN" ]] && write_collector_env FRESHCHOICE_ORIGIN "$FRESHCHOICE_ORIGIN"
chmod 600 "$ENV_FILE"
printf '  %s✓ perms%s %s set to 600 (owner-only)\n' "$GREEN" "$RESET" "$ENV_FILE"
if ! grep -qE '^collector\.env$' "$REPO_PATH/.gitignore" 2>/dev/null; then
  warn "collector.env is NOT gitignored — add it before committing anything!"
fi

# ── Stage 3: render the launchd plist ─────────────────────────────────────
stage "Render launchd plist"
TPL="$REPO_PATH/ops/nz.grocery-prices.archive.daemon.plist.template"
PLIST_OUT="/tmp/nz.grocery-prices.archive.plist"
sed -e "s|/REPLACE/WITH/ABSOLUTE/PATH/scripts/archive-daily-local.sh|$REPO_PATH/scripts/archive-daily-local.sh|" \
    -e "s|<string>/REPLACE/WITH/ABSOLUTE/PATH</string>|<string>$REPO_PATH</string>|" \
    -e "s|REPLACE_WITH_COLLECTOR_USERNAME|$(whoami)|" \
    -e "s|<string>/REPLACE/WITH/ABSOLUTE/PATH/collector.env</string>|<string>$ENV_FILE</string>|" \
    "$TPL" > "$PLIST_OUT"
if plutil -lint "$PLIST_OUT" >/dev/null; then
  printf '  %s✓ rendered%s %s (lint OK)\n' "$GREEN" "$RESET" "$PLIST_OUT"
else
  warn "plist failed lint — inspect $PLIST_OUT"; exit 1
fi
note "Schedule: daily at 04:00 · logs: /tmp/nz-grocery-prices-archive.log"

# ── Stage 4: install (sudo) ───────────────────────────────────────────────
stage "Install daemon (sudo)"
say "This copies the plist to /Library/LaunchDaemons and registers it with"
say "launchd. macOS will prompt for your password once."
if ! confirm "Install now?"; then
  say "Skipped. Install later with:"
  note "  sudo cp $PLIST_OUT /Library/LaunchDaemons/nz.grocery-prices.archive.plist"
  note "  sudo plutil -lint /Library/LaunchDaemons/nz.grocery-prices.archive.plist"
  note "  sudo chown root:wheel /Library/LaunchDaemons/nz.grocery-prices.archive.plist"
  note "  sudo chmod 644 /Library/LaunchDaemons/nz.grocery-prices.archive.plist"
  note "  sudo launchctl bootstrap system /Library/LaunchDaemons/nz.grocery-prices.archive.plist"
  SKIPPED+=("daemon installation")
else
  sudo cp "$PLIST_OUT" /Library/LaunchDaemons/nz.grocery-prices.archive.plist
  sudo plutil -lint /Library/LaunchDaemons/nz.grocery-prices.archive.plist
  sudo chown root:wheel /Library/LaunchDaemons/nz.grocery-prices.archive.plist
  sudo chmod 644 /Library/LaunchDaemons/nz.grocery-prices.archive.plist
  if sudo launchctl print system/nz.grocery-prices.archive >/dev/null 2>&1; then
    say "Already registered — recycling it instead."
    sudo launchctl bootout system/nz.grocery-prices.archive || true
  fi
  sudo launchctl bootstrap system /Library/LaunchDaemons/nz.grocery-prices.archive.plist
  printf '  %s✓ installed%s nz.grocery-prices.archive (daily 04:00)\n' "$GREEN" "$RESET"
fi

# ── Stage 5: test run now + verify fresh data ─────────────────────────────
stage "Test run & verify"
if confirm "Trigger one collection right now (takes ~a few minutes)?"; then
  lines_before=$(wc -l < "$REPO_PATH/data/prices.jsonl" 2>/dev/null || echo 0)
  sudo launchctl kickstart -k system/nz.grocery-prices.archive
  say "Collection started. Waiting for it to finish…"
  while sudo launchctl print system/nz.grocery-prices.archive 2>/dev/null \
        | grep -q 'state = "running"'; do sleep 10; done
  lines_after=$(wc -l < "$REPO_PATH/data/prices.jsonl")
  say "archive records: $lines_before → $lines_after"
  if (( lines_after > lines_before )); then
    printf '  %s✓ fresh data landed%s\n' "$GREEN" "$RESET"
  else
    warn "no new records — check /tmp/nz-grocery-prices-archive.error.log"
  fi
  [[ -s /tmp/nz-grocery-prices-archive.error.log ]] && \
    note "last error-log lines:" && tail -3 /tmp/nz-grocery-prices-archive.error.log
  say "Per-retailer outcomes: $(ls "$REPO_PATH/data/collection-health.jsonl" 2>/dev/null || echo 'health log not created')"
else
  SKIPPED+=("test run (first automatic run is tomorrow 04:00)")
fi

finish
